#include <stdio.h>
#include <stddef.h>

struct Summary {
    int minimum;
    int maximum;
    long long total;
};

int summarize(const int values[], size_t count, struct Summary *out)
{
    size_t i;

    if (values == NULL || out == NULL || count == 0U) {
        return 0;
    }

    out->minimum = values[0];
    out->maximum = values[0];
    out->total = 0;

    for (i = 0U; i < count; ++i) {
        if (values[i] < out->minimum) {
            out->minimum = values[i];
        }
        if (values[i] > out->maximum) {
            out->maximum = values[i];
        }
        out->total += (long long)values[i];
    }
    return 1;
}

int main(void)
{
    const int values[] = { 8, -2, 5, 11, 0 };
    const size_t count = sizeof values / sizeof values[0];
    struct Summary result;

    if (!summarize(values, count, &result)) {
        puts("invalid input");
        return 1;
    }

    printf("count=%zu min=%d max=%d total=%lld\n",
           count, result.minimum, result.maximum, result.total);
    return 0;
}

#include <ctype.h>
#include <stdio.h>

int main(void)
{
    char line[128];
    size_t letters = 0U;
    size_t i;

    if (fgets(line, sizeof line, stdin) == NULL) {
        fputs("input error or end of file\n", stderr);
        return 1;
    }

    for (i = 0U; line[i] != '\0'; ++i) {
        if (isalpha((unsigned char)line[i]) != 0) {
            ++letters;
        }
    }

    printf("alphabetic-bytes=%zu\n", letters);
    return 0;
}
